import { appendFile, mkdir, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { getAiEvalsRoot, getRepoRoot } from "./cases";
import type {
  BenchmarkArtifactFile,
  BenchmarkAttemptResult,
  BenchmarkCaseResult,
  BenchmarkRunResult,
  BenchmarkTokenUsage,
  EvalMode,
} from "./types";

type AttemptAggregate = {
  attemptCount: number;
  durationTotal: number;
  tokenUsageAttemptCount: number;
  tokenUsageTotal: BenchmarkTokenUsage | null;
  finalContextAttemptCount: number;
  finalContextTotal: number;
  finalContextMax: number | null;
};

export async function writeRunResult(
  result: BenchmarkRunResult,
  outputPath?: string,
): Promise<string> {
  const targetPath = resolveRunOutputPath(result.mode, outputPath);
  await mkdir(path.dirname(targetPath), { recursive: true });
  await writeFile(
    targetPath,
    JSON.stringify(toSerializableRunResult(result), null, 2) + "\n",
    "utf8",
  );
  return targetPath;
}

export async function appendHistoryRecord(
  result: BenchmarkRunResult,
  historyPath = resolveHistoryPath(result.mode),
): Promise<string> {
  await mkdir(path.dirname(historyPath), { recursive: true });
  await appendFile(
    historyPath,
    JSON.stringify(toHistoryRecord(result)) + "\n",
    "utf8",
  );
  return historyPath;
}

export async function writeRunArtifacts(
  result: BenchmarkRunResult,
  outputPath?: string,
): Promise<string | null> {
  const targetPath = resolveRunOutputPath(result.mode, outputPath);
  const artifactRoot = defaultArtifactsRoot(targetPath);

  await rm(artifactRoot, { recursive: true, force: true });

  let wroteArtifacts = false;
  for (const caseResult of result.cases) {
    for (const attempt of caseResult.attempts) {
      const artifactFiles = attempt.artifactFiles ?? [];
      if (artifactFiles.length === 0) {
        attempt.artifactsPath = null;
        continue;
      }

      const attemptDir = path.join(
        artifactRoot,
        caseResult.id,
        `attempt-${attempt.attempt}`,
      );
      await writeArtifactFiles(attemptDir, artifactFiles);
      attempt.artifactsPath = attemptDir;
      wroteArtifacts = true;
    }
  }

  result.artifactsPath = wroteArtifacts ? artifactRoot : null;
  return result.artifactsPath ?? null;
}

export function buildRunResult(input: {
  mode: EvalMode;
  runs: number;
  runModel: string | null;
  judgeModel: string | null;
  caseResults: BenchmarkCaseResult[];
}): BenchmarkRunResult {
  const attempts = input.caseResults.flatMap((entry) => entry.attempts);
  const passedAttemptResults = attempts.filter((attempt) => attempt.passed);
  const attemptAggregate = aggregateAttempts(attempts);
  const passedAttemptAggregate = aggregateAttempts(passedAttemptResults);
  const attemptCount = attemptAggregate.attemptCount;
  const passedAttempts = passedAttemptAggregate.attemptCount;

  return {
    version: 1,
    mode: input.mode,
    createdAt: new Date().toISOString(),
    gitSha: getGitSha(),
    runs: input.runs,
    runModel: input.runModel,
    judgeModel: input.judgeModel,
    caseCount: input.caseResults.length,
    attemptCount,
    passedAttempts,
    passRate: attemptCount === 0 ? 0 : passedAttempts / attemptCount,
    averageDurationMs:
      attemptCount === 0 ? 0 : attemptAggregate.durationTotal / attemptCount,
    averagePassedDurationMs: averageDuration(passedAttemptAggregate),
    totalTokenUsage: attemptAggregate.tokenUsageTotal,
    totalPassedTokenUsage: passedAttemptAggregate.tokenUsageTotal,
    averageTokenUsagePerAttempt:
      attemptCount === 0
        ? null
        : averageTokenUsage(attemptAggregate, attemptCount),
    averageTokenUsagePerPassedAttempt: averageTokenUsage(
      passedAttemptAggregate,
      passedAttempts,
    ),
    averageFinalContextTokensPassed: averageFinalContext(passedAttemptAggregate),
    maxFinalContextTokensPassed: passedAttemptAggregate.finalContextMax,
    cases: input.caseResults,
  };
}

export function formatRunSummary(result: BenchmarkRunResult): string {
  const lines = [
    `${result.mode} benchmark complete`,
    `Pass rate: ${formatPercent(result.passRate)} (${result.passedAttempts}/${result.attemptCount})`,
    `Average duration (passed): ${formatNullableDuration(result.averagePassedDurationMs ?? null)}`,
  ];

  if (result.averageTokenUsagePerPassedAttempt) {
    lines.push(
      `Average tokens (passed): ${formatTokenUsage(result.averageTokenUsagePerPassedAttempt)}`,
    );
  }
  if (result.averageFinalContextTokensPassed != null) {
    lines.push(
      `Final context size (passed): ${Math.round(result.averageFinalContextTokensPassed)} tokens (max ${Math.round(result.maxFinalContextTokensPassed ?? 0)})`,
    );
  }
  if (result.passedAttempts < result.attemptCount) {
    lines.push(
      `Average duration (all attempts): ${Math.round(result.averageDurationMs)}ms`,
    );
    if (result.averageTokenUsagePerAttempt) {
      lines.push(
        `Average tokens (all attempts): ${formatTokenUsage(result.averageTokenUsagePerAttempt)}`,
      );
    }
  }

  const failures = collectFailures(result);
  if (failures.length > 0) {
    lines.push("Failures:");
    for (const entry of failures.slice(0, 10)) {
      lines.push(`- ${entry}`);
    }
  }

  return lines.join("\n");
}

function collectFailures(result: BenchmarkRunResult): string[] {
  const failures: string[] = [];

  for (const caseResult of result.cases) {
    for (const attempt of caseResult.attempts) {
      if (attempt.passed) {
        continue;
      }
      const failedChecks = attempt.checks
        .filter((check) => !check.passed)
        .map((check) => check.name);
      failures.push(
        `${caseResult.id} attempt ${attempt.attempt}: ${failedChecks.join(", ") || attempt.error || "failed"}`,
      );
    }
  }

  return failures;
}

function aggregateAttempts(attempts: BenchmarkAttemptResult[]): AttemptAggregate {
  const aggregate: AttemptAggregate = {
    attemptCount: attempts.length,
    durationTotal: 0,
    tokenUsageAttemptCount: 0,
    tokenUsageTotal: null,
    finalContextAttemptCount: 0,
    finalContextTotal: 0,
    finalContextMax: null,
  };

  for (const attempt of attempts) {
    aggregate.durationTotal += attempt.durationMs;
    if (typeof attempt.finalContextTokens === "number") {
      aggregate.finalContextAttemptCount += 1;
      aggregate.finalContextTotal += attempt.finalContextTokens;
      aggregate.finalContextMax = Math.max(
        aggregate.finalContextMax ?? 0,
        attempt.finalContextTokens,
      );
    }
    if (!attempt.tokenUsage) {
      continue;
    }
    aggregate.tokenUsageAttemptCount += 1;
    aggregate.tokenUsageTotal ??= { prompt: 0, completion: 0, total: 0 };
    aggregate.tokenUsageTotal.prompt += attempt.tokenUsage.prompt;
    aggregate.tokenUsageTotal.completion += attempt.tokenUsage.completion;
    aggregate.tokenUsageTotal.total += attempt.tokenUsage.total;
  }

  return aggregate;
}

function averageDuration(aggregate: AttemptAggregate): number | null {
  return aggregate.attemptCount === 0
    ? null
    : aggregate.durationTotal / aggregate.attemptCount;
}

function averageFinalContext(aggregate: AttemptAggregate): number | null {
  return aggregate.finalContextAttemptCount === 0
    ? null
    : aggregate.finalContextTotal / aggregate.finalContextAttemptCount;
}

function averageTokenUsage(
  aggregate: AttemptAggregate,
  denominator: number,
): BenchmarkTokenUsage | null {
  if (denominator === 0 || !aggregate.tokenUsageTotal) {
    return null;
  }
  return {
    prompt: aggregate.tokenUsageTotal.prompt / denominator,
    completion: aggregate.tokenUsageTotal.completion / denominator,
    total: aggregate.tokenUsageTotal.total / denominator,
  };
}

function formatNullableDuration(value: number | null): string {
  return value === null ? "n/a" : `${Math.round(value)}ms`;
}

function formatTokenUsage(value: BenchmarkTokenUsage): string {
  const total = Math.round(value.total);
  const prompt = Math.round(value.prompt);
  const completion = Math.round(value.completion);
  return `${total} total (${prompt} prompt, ${completion} completion)`;
}

function defaultFileName(mode: EvalMode): string {
  return `${new Date().toISOString().replaceAll(":", "-")}__${mode}.json`;
}

export function resolveRunOutputPath(
  mode: EvalMode,
  outputPath?: string,
): string {
  return (
    outputPath ?? path.join(getAiEvalsRoot(), "results", defaultFileName(mode))
  );
}

export function resolveHistoryPath(mode: EvalMode): string {
  return path.join(getAiEvalsRoot(), "history", `${mode}.jsonl`);
}

function defaultArtifactsRoot(resultPath: string): string {
  return resultPath.endsWith(".json")
    ? resultPath.slice(0, -".json".length)
    : `${resultPath}.artifacts`;
}

async function writeArtifactFiles(
  rootDir: string,
  files: BenchmarkArtifactFile[],
): Promise<void> {
  for (const file of files) {
    const relativePath = normalizeArtifactPath(file.path);
    const targetPath = path.join(rootDir, relativePath);
    await mkdir(path.dirname(targetPath), { recursive: true });
    await writeFile(targetPath, file.content, "utf8");
  }
}

function normalizeArtifactPath(filePath: string): string {
  const normalized = filePath.replaceAll("\\", "/").replace(/^\/+/, "");
  const parts = normalized.split("/").filter(Boolean);
  if (
    parts.length === 0 ||
    parts.some((part) => part === "." || part === "..")
  ) {
    throw new Error(`Invalid artifact path: ${filePath}`);
  }
  return parts.join("/");
}

function toSerializableRunResult(
  result: BenchmarkRunResult,
): BenchmarkRunResult {
  return {
    ...result,
    cases: result.cases.map((caseResult) => ({
      ...caseResult,
      attempts: caseResult.attempts.map(
        ({ artifactFiles, ...attempt }) => attempt,
      ),
    })),
  };
}

function toHistoryRecord(result: BenchmarkRunResult) {
  const judgeScores = result.cases.flatMap((caseResult) =>
    caseResult.attempts.flatMap((attempt) =>
      typeof attempt.judgeScore === "number" ? [attempt.judgeScore] : [],
    ),
  );

  return {
    createdAt: result.createdAt,
    gitSha: result.gitSha,
    mode: result.mode,
    runs: result.runs,
    runModel: result.runModel,
    judgeModel: result.judgeModel,
    caseCount: result.caseCount,
    attemptCount: result.attemptCount,
    passedAttempts: result.passedAttempts,
    passRate: result.passRate,
    averageDurationMs: result.averageDurationMs,
    averagePassedDurationMs: result.averagePassedDurationMs ?? null,
    averageJudgeScore:
      judgeScores.length === 0
        ? null
        : judgeScores.reduce((sum, score) => sum + score, 0) /
          judgeScores.length,
    averageTokenUsagePerAttempt: result.averageTokenUsagePerAttempt ?? null,
    averageTokenUsagePerPassedAttempt:
      result.averageTokenUsagePerPassedAttempt ?? null,
    averageFinalContextTokensPassed:
      result.averageFinalContextTokensPassed ?? null,
    maxFinalContextTokensPassed: result.maxFinalContextTokensPassed ?? null,
    failedCaseIds: Array.from(
      new Set(
        result.cases
          .filter((caseResult) =>
            caseResult.attempts.some((attempt) => !attempt.passed),
          )
          .map((caseResult) => caseResult.id),
      ),
    ),
    cases: result.cases.map((caseResult) => {
      const attemptAggregate = aggregateAttempts(caseResult.attempts);
      const passedAttemptAggregate = aggregateAttempts(
        caseResult.attempts.filter((attempt) => attempt.passed),
      );
      const attemptCount = attemptAggregate.attemptCount;
      const passedAttempts = passedAttemptAggregate.attemptCount;
      const judgeScores = caseResult.attempts.flatMap((attempt) =>
        typeof attempt.judgeScore === "number" ? [attempt.judgeScore] : [],
      );

      return {
        id: caseResult.id,
        attemptCount,
        passedAttempts,
        passRate: attemptCount === 0 ? 0 : passedAttempts / attemptCount,
        averageDurationMs:
          attemptCount === 0
            ? 0
            : attemptAggregate.durationTotal / attemptCount,
        averagePassedDurationMs: averageDuration(passedAttemptAggregate),
        averageJudgeScore:
          judgeScores.length === 0
            ? null
            : judgeScores.reduce((sum, score) => sum + score, 0) /
              judgeScores.length,
        averageTokenUsagePerAttempt:
          attemptCount === 0
            ? null
            : averageTokenUsage(attemptAggregate, attemptCount),
        averageTokenUsagePerPassedAttempt: averageTokenUsage(
          passedAttemptAggregate,
          passedAttempts,
        ),
        averageFinalContextTokensPassed: averageFinalContext(
          passedAttemptAggregate,
        ),
        maxFinalContextTokensPassed: passedAttemptAggregate.finalContextMax,
      };
    }),
  };
}

function getGitSha(): string | null {
  try {
    return execFileSync("git", ["rev-parse", "HEAD"], {
      cwd: getRepoRoot(),
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
  } catch {
    return null;
  }
}

function formatPercent(value: number): string {
  return `${(value * 100).toFixed(1)}%`;
}

import { describe, expect, it } from "bun:test";
import { runSuite } from "./runSuite";
import type { ModeRunner } from "./types";

const modeRunner: ModeRunner<undefined, undefined, { ok: boolean }> = {
  mode: "global",
  concurrency: 1,
  loadInitial: async () => undefined,
  loadExpected: async () => undefined,
  run: async () => ({
    success: true,
    actual: { ok: true },
    assistantMessageCount: 1,
    toolCallCount: 0,
    toolsUsed: [],
    skillsInvoked: [],
    tokenUsage: null,
  }),
  validate: () => [],
};

describe("runSuite", () => {
  it("skips judge checks when the run disables judge scoring", async () => {
    const [caseResult] = await runSuite({
      modeRunner,
      cases: [
        {
          id: "case-1",
          prompt: "Create a draft script",
          judgeChecklist: ["the output satisfies the prompt"],
        },
      ],
      runs: 1,
      runModel: "model-under-test",
      judgeModel: null,
    });

    const [attempt] = caseResult.attempts;
    expect(attempt.passed).toBe(true);
    expect(attempt.judgeScore).toBeNull();
    expect(attempt.judgeSummary).toBeNull();
    expect(attempt.checks.map((check) => check.name)).toEqual([
      "run succeeded",
    ]);
  });

  it("only requires run success when execution-only is enabled", async () => {
    let loadExpectedCalls = 0;
    let validateCalls = 0;
    let backendValidateCalls = 0;

    const executionOnlyRunner: ModeRunner<
      undefined,
      undefined,
      { ok: boolean }
    > = {
      ...modeRunner,
      loadExpected: async () => {
        loadExpectedCalls++;
        return undefined;
      },
      validate: () => {
        validateCalls++;
        return [{ name: "validator failed", passed: false }];
      },
      backendValidate: async () => {
        backendValidateCalls++;
        return {
          checks: [{ name: "backend validation failed", passed: false }],
        };
      },
    };

    const [caseResult] = await runSuite({
      modeRunner: executionOnlyRunner,
      cases: [
        {
          id: "case-1",
          prompt: "Create a draft script",
          expectedPath: "fixtures/expected.json",
          toolExpect: { requiredToolsUsed: ["write_script"] },
          judgeChecklist: ["the output satisfies the prompt"],
        },
      ],
      runs: 1,
      runModel: "model-under-test",
      judgeModel: "judge-model",
      executionOnly: true,
    });

    const [attempt] = caseResult.attempts;
    expect(attempt.passed).toBe(true);
    expect(attempt.judgeScore).toBeNull();
    expect(attempt.judgeSummary).toBeNull();
    expect(attempt.checks.map((check) => check.name)).toEqual([
      "run succeeded",
    ]);
    expect(loadExpectedCalls).toBe(0);
    expect(validateCalls).toBe(0);
    expect(backendValidateCalls).toBe(0);
  });
});

import { judgeOutput, DEFAULT_JUDGE_MODEL } from "./judge";
import type {
  BenchmarkAttemptResult,
  BenchmarkCaseResult,
  BenchmarkCheck,
  EvalCase,
  FrontendBenchmarkProgressEvent,
  ModeRunner,
} from "./types";
import { validateToolExpectations } from "./validators";

export async function runSuite<TInitial, TExpected, TActual>(input: {
  modeRunner: ModeRunner<TInitial, TExpected, TActual>;
  cases: EvalCase[];
  runs: number;
  runModel: string | null;
  judgeModel?: string | null;
  executionOnly?: boolean;
  concurrency?: number;
  verbose?: boolean;
  onProgress?: (event: FrontendBenchmarkProgressEvent) => void;
}): Promise<BenchmarkCaseResult[]> {
  const judgeModel =
    input.judgeModel === undefined ? DEFAULT_JUDGE_MODEL : input.judgeModel;
  const concurrency = Math.max(1, input.concurrency ?? input.modeRunner.concurrency);
  const results = new Array<BenchmarkCaseResult>(input.cases.length);
  let cursor = 0;

  if (input.modeRunner.mode !== "cli") {
    input.onProgress?.({
      type: "run-start",
      surface: input.modeRunner.mode,
      totalCases: input.cases.length,
      runs: input.runs,
      concurrency,
    });
  }

  async function worker(): Promise<void> {
    while (true) {
      const caseIndex = cursor++;
      if (caseIndex >= input.cases.length) {
        return;
      }
      const evalCase = input.cases[caseIndex];
      results[caseIndex] = {
        id: evalCase.id,
        prompt: evalCase.prompt,
        initialPath: evalCase.initialPath,
        expectedPath: evalCase.expectedPath,
        attempts: await runCaseAttempts({
          caseIndex,
          evalCase,
          runs: input.runs,
          judgeModel,
          judgeThreshold: input.modeRunner.judgeThreshold ?? 80,
          executionOnly: input.executionOnly ?? false,
          modeRunner: input.modeRunner,
          totalCases: input.cases.length,
          verbose: input.verbose ?? false,
          onProgress: input.onProgress,
        }),
      };
    }
  }

  await Promise.all(
    Array.from({ length: Math.min(concurrency, input.cases.length) }, () => worker())
  );

  return results;
}

async function runCaseAttempts<TInitial, TExpected, TActual>(input: {
  caseIndex: number;
  evalCase: EvalCase;
  runs: number;
  judgeModel: string | null;
  judgeThreshold: number;
  executionOnly: boolean;
  modeRunner: ModeRunner<TInitial, TExpected, TActual>;
  totalCases: number;
  verbose: boolean;
  onProgress?: (event: FrontendBenchmarkProgressEvent) => void;
}): Promise<BenchmarkAttemptResult[]> {
  const attempts: BenchmarkAttemptResult[] = [];
  const surface = input.modeRunner.mode === "cli" ? null : input.modeRunner.mode;

  for (let attempt = 1; attempt <= input.runs; attempt += 1) {
    if (surface) {
      input.onProgress?.({
        type: "attempt-start",
        surface,
        caseId: input.evalCase.id,
        caseNumber: input.caseIndex + 1,
        totalCases: input.totalCases,
        attempt,
        runs: input.runs,
      });
    }

    const startedAt = Date.now();

    try {
      const initial = await input.modeRunner.loadInitial(input.evalCase.initialPath);
      const expected = input.executionOnly
        ? undefined
        : await input.modeRunner.loadExpected(input.evalCase.expectedPath);
      const run = await input.modeRunner.run(input.evalCase.prompt, initial, {
        evalCase: input.evalCase,
        caseId: input.evalCase.id,
        caseNumber: input.caseIndex + 1,
        totalCases: input.totalCases,
        attempt,
        runs: input.runs,
        verbose: input.verbose,
        onAssistantMessageStart: input.verbose && surface
          ? () =>
              input.onProgress?.({
                type: "assistant-message-start",
                surface,
                caseId: input.evalCase.id,
                caseNumber: input.caseIndex + 1,
                totalCases: input.totalCases,
                attempt,
                runs: input.runs,
              })
          : undefined,
        onAssistantChunk: input.verbose && surface
          ? (chunk: string) =>
              input.onProgress?.({
                type: "assistant-chunk",
                surface,
                caseId: input.evalCase.id,
                caseNumber: input.caseIndex + 1,
                totalCases: input.totalCases,
                attempt,
                runs: input.runs,
                chunk,
              })
          : undefined,
        onAssistantMessageEnd: input.verbose && surface
          ? () =>
              input.onProgress?.({
                type: "assistant-message-end",
                surface,
                caseId: input.evalCase.id,
                caseNumber: input.caseIndex + 1,
                totalCases: input.totalCases,
                attempt,
                runs: input.runs,
              })
          : undefined,
        onToolCall: input.verbose && surface
          ? ({ toolName, argumentsText }) =>
              input.onProgress?.({
                type: "tool-call",
                surface,
                caseId: input.evalCase.id,
                caseNumber: input.caseIndex + 1,
                totalCases: input.totalCases,
                attempt,
                runs: input.runs,
                toolName,
                argumentsText,
              })
          : undefined,
      });
      const checks: BenchmarkCheck[] = [
        buildCheck("run succeeded", run.success, run.error),
      ];
      if (!input.executionOnly) {
        checks.push(
          ...input.modeRunner.validate({
            evalCase: input.evalCase,
            prompt: input.evalCase.prompt,
            initial,
            expected,
            actual: run.actual,
            run,
          }),
          ...validateToolExpectations({
            run,
            toolExpect: input.evalCase.toolExpect,
          })
        );
      }
      const artifactFiles = input.modeRunner.buildArtifacts?.(run.actual) ?? [];

      if (
        run.success &&
        !input.executionOnly &&
        input.modeRunner.backendValidate
      ) {
        try {
          const backendValidation = await input.modeRunner.backendValidate({
            evalCase: input.evalCase,
            prompt: input.evalCase.prompt,
            initial,
            expected,
            actual: run.actual,
            run,
            context: {
              evalCase: input.evalCase,
              caseId: input.evalCase.id,
              caseNumber: input.caseIndex + 1,
              totalCases: input.totalCases,
              attempt,
              runs: input.runs,
              verbose: input.verbose,
              onAssistantMessageStart: undefined,
              onAssistantChunk: undefined,
              onAssistantMessageEnd: undefined,
            },
          });

          if (backendValidation) {
            checks.push(...backendValidation.checks);
            artifactFiles.push(...(backendValidation.artifactFiles ?? []));
          }
        } catch (error) {
          checks.push(
            buildCheck(
              "backend validation succeeded",
              false,
              error instanceof Error ? error.message : String(error)
            )
          );
        }
      }

      let judgeScore: number | null = null;
      let judgeSummary: string | null = null;

      if (
        run.success &&
        !input.executionOnly &&
        input.judgeModel !== null &&
        !input.evalCase.skipJudge
      ) {
        const judge = await judgeOutput({
          mode: input.modeRunner.mode,
          prompt: input.evalCase.prompt,
          checklist: input.evalCase.judgeChecklist,
          initial,
          expected: input.modeRunner.mode === "cli" ? undefined : expected,
          actual: input.modeRunner.prepareJudgeActual
            ? input.modeRunner.prepareJudgeActual(run.actual)
            : run.actual,
          model: input.judgeModel,
        });

        judgeScore = judge.success ? judge.score : null;
        judgeSummary = judge.summary;
        checks.push(buildCheck("judge succeeded", judge.success, judge.error));
        checks.push(
          buildCheck(
            `judge score >= ${input.judgeThreshold}`,
            (judgeScore ?? 0) >= input.judgeThreshold,
            judge.success ? `score=${judgeScore}` : judge.error
          )
        );
      }

      const attemptResult: BenchmarkAttemptResult = {
        attempt,
        passed: checks.every((check) => check.passed),
        durationMs: Date.now() - startedAt,
        assistantMessageCount: run.assistantMessageCount,
        toolCallCount: run.toolCallCount,
        toolsUsed: uniqueStrings(run.toolsUsed),
        toolCallDetails: run.toolCallDetails,
        skillsInvoked: uniqueStrings(run.skillsInvoked),
        checks,
        judgeScore,
        judgeSummary,
        error: run.error ?? null,
        tokenUsage: run.tokenUsage ?? null,
        finalContextTokens: run.finalContextTokens ?? null,
        artifactsPath: null,
        artifactFiles,
      };

      if (surface) {
        input.onProgress?.({
          type: "attempt-finish",
          surface,
          caseId: input.evalCase.id,
          caseNumber: input.caseIndex + 1,
          totalCases: input.totalCases,
          attempt,
          runs: input.runs,
          passed: attemptResult.passed,
          durationMs: attemptResult.durationMs,
          judgeScore: attemptResult.judgeScore,
          error: attemptResult.error,
        });
      }

      attempts.push(attemptResult);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      const failedAttempt: BenchmarkAttemptResult = {
        attempt,
        passed: false,
        durationMs: Date.now() - startedAt,
        assistantMessageCount: 0,
        toolCallCount: 0,
        toolsUsed: [],
        skillsInvoked: [],
        checks: [buildCheck("run crashed", false, message)],
        judgeScore: null,
        judgeSummary: null,
        error: message,
        tokenUsage: null,
        finalContextTokens: null,
      };
      if (surface) {
        input.onProgress?.({
          type: "attempt-finish",
          surface,
          caseId: input.evalCase.id,
          caseNumber: input.caseIndex + 1,
          totalCases: input.totalCases,
          attempt,
          runs: input.runs,
          passed: false,
          durationMs: failedAttempt.durationMs,
          judgeScore: null,
          error: message,
        });
      }
      attempts.push(failedAttempt);
    }
  }

  return attempts;
}

function buildCheck(name: string, passed: boolean, details?: string): BenchmarkCheck {
  return details ? { name, passed, details } : { name, passed };
}

function uniqueStrings(values: string[]): string[] {
  return [...new Set(values)];
}

export const EVAL_MODES = ["cli", "flow", "script", "app", "global"] as const;

export type EvalMode = (typeof EVAL_MODES)[number];

export interface EvalCaseRuntimeBackendPreview {
  args?: Record<string, unknown>;
  timeoutSeconds?: number;
}

export type EvalCaseRuntimeAppAdditionalContext =
  | {
      type: "frontend";
      path: string;
    }
  | {
      type: "backend";
      key: string;
    }
  | {
      type: "datatable";
      datatableName: string;
      schema: string;
      table: string;
    };

export interface EvalCaseRuntimeAppContextSpec {
  additional?: EvalCaseRuntimeAppAdditionalContext[];
}

export interface EvalCaseRuntimeSpec {
  maxTurns?: number;
  backendPreview?: EvalCaseRuntimeBackendPreview;
  appContext?: EvalCaseRuntimeAppContextSpec;
  // Global mode: run as a session chat (preview tools + session prompt) vs the standalone chat.
  sessionChat?: boolean;
}

export interface FlowValidationSpec {
  schemaRequiredPaths?: string[];
  schemaAnyOf?: Array<{
    requiredPaths: string[];
  }>;
  exactTopLevelStepIds?: string[];
  topLevelStepIds?: string[];
  topLevelStepOrder?: string[];
  topLevelStepTypeCountsAtLeast?: Array<{
    type: string;
    count: number;
  }>;
  topLevelStepTypes?: Array<{
    id: string;
    type: string | string[];
  }>;
  moduleRules?: Array<{
    id: string;
    hasStopAfterIf?: boolean;
    hasStopAfterAllItersIf?: boolean;
    immediateChildStepIds?: string[];
    exactImmediateChildStepIds?: string[];
    immediateChildStepTypes?: Array<{
      id: string;
      type: string;
    }>;
    requiredInputTransforms?: Array<{
      type?: string;
      expr?: string;
      exprAnyOf?: string[];
      value?: string | number | boolean | null;
    }>;
  }>;
  moduleFieldRules?: Array<{
    id: string;
    path: string;
    equals: string | number | boolean | null;
  }>;
  resolveResultsRefs?: boolean;
  requireSpecialModules?: Array<"preprocessor_module" | "failure_module">;
  requireSuspendSteps?: Array<{
    id: string;
    requiredEvents?: number;
    resumeRequiredStringFieldAnyOf?: string[];
  }>;
}

export interface AppValidationSpec {
  requiredFrontendPaths?: string[];
  requiredFrontendFileContent?: Array<{
    path: string;
    includes: string[];
  }>;
  requiredBackendRunnableKeys?: string[];
  requiredBackendRunnableTypes?: Array<{
    key: string;
    type: string;
  }>;
  requiredBackendRunnableContent?: Array<{
    key: string;
    includes: string[];
  }>;
  backendRunnableCountAtLeast?: number;
  datatableCountAtLeast?: number;
  datatableTableCountAtLeast?: number;
  datatableTableCountExactly?: number;
  requiredDatatables?: Array<{
    schema: string;
    table: string;
    datatableName?: string;
  }>;
  requiredToolsUsed?: string[];
  forbiddenAppContent?: string[];
}

export interface GlobalDraftRequirement {
  type: string;
  path?: string;
  pathIncludes?: string[];
  pathStartsWith?: string;
  triggerKind?: string;
  language?: string;
  summaryIncludes?: string[];
  valueIncludes?: string[];
  valueExcludes?: string[];
}

export interface GlobalValidationSpec {
  draftCountAtLeast?: number;
  draftCountExactly?: number;
  requiredDrafts?: GlobalDraftRequirement[];
  forbiddenDrafts?: Array<{
    type: string;
    path: string;
    triggerKind?: string;
  }>;
}

export interface CliValidationSpec {
  requiredSkills?: string[];
  forbiddenSkills?: string[];
  requiredSkillsBeforeFirstMutation?: string[];
  requiredAssistantMentions?: string[];
  forbiddenAssistantMentions?: string[];
  orderedAssistantMentions?: string[];
  requiredProposedCommands?: string[];
  forbiddenProposedCommands?: string[];
  orderedProposedCommands?: string[];
  forbiddenExecutedCommands?: string[];
  workspaceUnchanged?: boolean;
}

export interface ToolCallDetail {
  name: string;
  arguments: unknown;
}

export interface ToolCallArgumentRule {
  tool: string;
  field: string;
  stringStartsWithAnyOf?: string[];
  stringMustNotStartWithAnyOf?: string[];
  /**
   * Case-insensitive "contains", existential over calls: at least one recorded
   * call to `tool` must have `field` containing one of these substrings. Other
   * calls to the same tool may do anything. Use instead of `stringStartsWithAnyOf`
   * (which is universal over calls) when the meaningful token can appear anywhere
   * in the value and the model may make additional, unrelated calls to the same
   * tool — e.g. SQL where a mutation is mixed with verification SELECTs.
   */
  stringIncludesAnyOf?: string[];
}

export interface ToolValidationSpec {
  requiredToolsUsed?: string[];
  /**
   * Each inner array is an alternatives group: the check passes when at least
   * one tool in the group was used. Use when several tools satisfy the same
   * intent so a model that picks any valid path passes — e.g. inspecting an
   * app's files via either `read_app_file` or `search_app`.
   */
  requiredToolsAnyOf?: string[][];
  forbiddenToolsUsed?: string[];
  toolCallArgs?: ToolCallArgumentRule[];
}

export type EvalValidationSpec =
  | FlowValidationSpec
  | AppValidationSpec
  | GlobalValidationSpec;

export interface EvalCase {
  id: string;
  prompt: string;
  initialPath?: string;
  expectedPath?: string;
  validate?: EvalValidationSpec;
  toolExpect?: ToolValidationSpec;
  cliExpect?: CliValidationSpec;
  judgeChecklist?: string[];
  skipJudge?: boolean;
  runtime?: EvalCaseRuntimeSpec;
}

export interface BenchmarkCheck {
  name: string;
  passed: boolean;
  details?: string;
}

export interface JudgeResult {
  success: boolean;
  score: number;
  summary: string;
  error?: string;
}

export interface BenchmarkArtifactFile {
  path: string;
  content: string;
}

export interface BackendValidationResult {
  checks: BenchmarkCheck[];
  artifactFiles?: BenchmarkArtifactFile[];
}

export interface BenchmarkTokenUsage {
  prompt: number;
  completion: number;
  total: number;
}

export interface CliToolInvocation {
  tool: string;
  input: Record<string, unknown>;
  timestamp: number;
}

export interface CliWmillInvocation {
  argv: string[];
  cwd: string;
  timestamp: string;
}

export interface CliTrace {
  toolsUsed: CliToolInvocation[];
  skillsInvoked: string[];
  assistantMessageCount: number;
  bashCommands: string[];
  proposedCommands: string[];
  executedWmillCommands: string[];
  wmillInvocations: CliWmillInvocation[];
  firstMutationToolIndex: number | null;
}

export interface ModeRunOutput<TActual> {
  success: boolean;
  actual: TActual;
  error?: string;
  assistantMessageCount: number;
  toolCallCount: number;
  toolsUsed: string[];
  toolCallDetails?: ToolCallDetail[];
  skillsInvoked: string[];
  tokenUsage?: BenchmarkTokenUsage | null;
  /**
   * Total input tokens occupying the context window on the LAST model request
   * of the agentic loop (input + cache-creation + cache-read). Complements the
   * cumulative `tokenUsage.prompt`, which sums every iteration's input.
   */
  finalContextTokens?: number | null;
}

export interface ModeRunContext {
  evalCase?: EvalCase;
  caseId: string;
  caseNumber: number;
  totalCases: number;
  attempt: number;
  runs: number;
  verbose: boolean;
  onAssistantMessageStart?: () => void;
  onAssistantChunk?: (chunk: string) => void;
  onAssistantMessageEnd?: () => void;
  onToolCall?: (input: { toolName: string; argumentsText: string }) => void;
}

export interface ModeRunner<TInitial, TExpected, TActual> {
  mode: EvalMode;
  concurrency: number;
  judgeThreshold?: number;
  loadInitial(path?: string): Promise<TInitial | undefined>;
  loadExpected(path?: string): Promise<TExpected | undefined>;
  run(
    prompt: string,
    initial: TInitial | undefined,
    context: ModeRunContext,
  ): Promise<ModeRunOutput<TActual>>;
  validate(input: {
    evalCase: EvalCase;
    prompt: string;
    initial: TInitial | undefined;
    expected: TExpected | undefined;
    actual: TActual;
    run: ModeRunOutput<TActual>;
  }): BenchmarkCheck[];
  backendValidate?(input: {
    evalCase: EvalCase;
    prompt: string;
    initial: TInitial | undefined;
    expected: TExpected | undefined;
    actual: TActual;
    run: ModeRunOutput<TActual>;
    context: ModeRunContext;
  }): Promise<BackendValidationResult | null>;
  buildArtifacts?(actual: TActual): BenchmarkArtifactFile[];
  /**
   * Optional transform applied to `actual` before it is handed to the LLM judge.
   * Use it to strip fields the judge must stay blind to (e.g. which docs-tool
   * arm produced an answer). When omitted, the judge receives `actual` as-is.
   */
  prepareJudgeActual?(actual: TActual): unknown;
}

export interface BenchmarkAttemptResult {
  attempt: number;
  passed: boolean;
  durationMs: number;
  assistantMessageCount: number;
  toolCallCount: number;
  toolsUsed: string[];
  toolCallDetails?: ToolCallDetail[];
  skillsInvoked: string[];
  checks: BenchmarkCheck[];
  judgeScore: number | null;
  judgeSummary: string | null;
  error: string | null;
  tokenUsage?: BenchmarkTokenUsage | null;
  finalContextTokens?: number | null;
  artifactsPath?: string | null;
  artifactFiles?: BenchmarkArtifactFile[];
}

export interface BenchmarkCaseResult {
  id: string;
  prompt: string;
  initialPath?: string;
  expectedPath?: string;
  attempts: BenchmarkAttemptResult[];
}

export interface BenchmarkRunResult {
  version: 1;
  mode: EvalMode;
  createdAt: string;
  gitSha: string | null;
  runs: number;
  runModel: string | null;
  judgeModel: string | null;
  caseCount: number;
  attemptCount: number;
  passedAttempts: number;
  passRate: number;
  averageDurationMs: number;
  averagePassedDurationMs?: number | null;
  totalTokenUsage?: BenchmarkTokenUsage | null;
  totalPassedTokenUsage?: BenchmarkTokenUsage | null;
  averageTokenUsagePerAttempt?: BenchmarkTokenUsage | null;
  averageTokenUsagePerPassedAttempt?: BenchmarkTokenUsage | null;
  averageFinalContextTokensPassed?: number | null;
  maxFinalContextTokensPassed?: number | null;
  artifactsPath?: string | null;
  cases: BenchmarkCaseResult[];
}

export type FrontendBenchmarkProgressEvent =
  | {
      type: "run-start";
      surface: Exclude<EvalMode, "cli">;
      totalCases: number;
      runs: number;
      concurrency: number;
    }
  | {
      type: "attempt-start";
      surface: Exclude<EvalMode, "cli">;
      caseId: string;
      caseNumber: number;
      totalCases: number;
      attempt: number;
      runs: number;
    }
  | {
      type: "attempt-finish";
      surface: Exclude<EvalMode, "cli">;
      caseId: string;
      caseNumber: number;
      totalCases: number;
      attempt: number;
      runs: number;
      passed: boolean;
      durationMs: number;
      judgeScore: number | null;
      error: string | null;
    }
  | {
      type: "assistant-message-start";
      surface: Exclude<EvalMode, "cli">;
      caseId: string;
      caseNumber: number;
      totalCases: number;
      attempt: number;
      runs: number;
    }
  | {
      type: "assistant-chunk";
      surface: Exclude<EvalMode, "cli">;
      caseId: string;
      caseNumber: number;
      totalCases: number;
      attempt: number;
      runs: number;
      chunk: string;
    }
  | {
      type: "assistant-message-end";
      surface: Exclude<EvalMode, "cli">;
      caseId: string;
      caseNumber: number;
      totalCases: number;
      attempt: number;
      runs: number;
    }
  | {
      type: "tool-call";
      surface: Exclude<EvalMode, "cli">;
      caseId: string;
      caseNumber: number;
      totalCases: number;
      attempt: number;
      runs: number;
      toolName: string;
      argumentsText: string;
    };

import { describe, expect, it } from "bun:test";
import {
  validateAppState,
  validateCliWorkspace,
  validateGlobalState,
  validateScriptState,
  validateToolExpectations,
} from "./validators";

describe("validateScriptState", () => {
  it("accepts semantically equivalent script implementations", () => {
    const checks = validateScriptState({
      actual: {
        path: "f/evals/greet_user.ts",
        lang: "bun",
        code: "export async function main(name: string): Promise<string> {\n  return `Hello, ${name}!`;\n}\n",
      },
      expected: {
        path: "f/evals/greet_user.ts",
        lang: "bun",
        code: "export async function main(name: string) {\n\treturn `Hello, ${name}!`\n}\n",
      },
    });

    expect(checks.every((check) => check.passed)).toBe(true);
  });

  it("still requires an exported main entrypoint", () => {
    const checks = validateScriptState({
      actual: {
        path: "f/evals/greet_user.ts",
        lang: "bun",
        code: "async function main(name: string) {\n  return `Hello, ${name}!`;\n}\n",
      },
    });

    expect(checks).toContainEqual({
      name: "script exports entrypoint",
      passed: false,
    });
  });
});

describe("validateToolExpectations", () => {
  it("accepts Windmill-prefixed schedule paths", () => {
    const checks = validateToolExpectations({
      run: {
        success: true,
        actual: {},
        assistantMessageCount: 1,
        toolCallCount: 1,
        toolsUsed: ["create_schedule"],
        toolCallDetails: [
          {
            name: "create_schedule",
            arguments: {
              path: "f/evals/greet_user_daily",
            },
          },
        ],
        skillsInvoked: [],
      },
      toolExpect: {
        requiredToolsUsed: ["create_schedule"],
        toolCallArgs: [
          {
            tool: "create_schedule",
            field: "path",
            stringStartsWithAnyOf: ["f/", "u/"],
            stringMustNotStartWithAnyOf: ["schedules/"],
          },
        ],
      },
    });

    expect(checks.every((check) => check.passed)).toBe(true);
  });

  it("rejects schedule-prefixed tool paths", () => {
    const checks = validateToolExpectations({
      run: {
        success: true,
        actual: {},
        assistantMessageCount: 1,
        toolCallCount: 1,
        toolsUsed: ["create_schedule"],
        toolCallDetails: [
          {
            name: "create_schedule",
            arguments: {
              path: "schedules/greet_user_daily",
            },
          },
        ],
        skillsInvoked: [],
      },
      toolExpect: {
        requiredToolsUsed: ["create_schedule"],
        toolCallArgs: [
          {
            tool: "create_schedule",
            field: "path",
            stringStartsWithAnyOf: ["f/", "u/"],
            stringMustNotStartWithAnyOf: ["schedules/"],
          },
        ],
      },
    });

    expect(checks).toContainEqual({
      name: "create_schedule.path uses an accepted prefix",
      passed: false,
      details: 'accepted prefixes: f/, u/; values: "schedules/greet_user_daily"',
    });
    expect(checks).toContainEqual({
      name: "create_schedule.path avoids rejected prefixes",
      passed: false,
      details: 'rejected prefixes: schedules/; values: "schedules/greet_user_daily"',
    });
  });

  it("rejects forbidden tool usage", () => {
    const checks = validateToolExpectations({
      run: {
        success: true,
        actual: {},
        assistantMessageCount: 1,
        toolCallCount: 1,
        toolsUsed: ["write_script", "deploy_workspace_item"],
        skillsInvoked: [],
      },
      toolExpect: {
        forbiddenToolsUsed: ["deploy_workspace_item"],
      },
    });

    expect(checks).toContainEqual({
      name: "does not use deploy_workspace_item",
      passed: false,
      details: "tools used: write_script, deploy_workspace_item",
    });
  });

  it("accepts a stringIncludesAnyOf substring regardless of case or position", () => {
    const checks = validateToolExpectations({
      run: {
