                "id": "validate_order",
                "value": {
                    "type": "rawscript",
                    "language": "bun",
                    "content": "export async function main(items: { name: string; price: number; quantity: number }[]) {\n  const invalid = items.filter(item => item.price <= 0 || item.quantity <= 0);\n  return { valid: invalid.length === 0, invalidItems: invalid };\n}",
