import { runFlowEval } from "../adapters/frontend/core/flow/flowEvalRunner";
import type { FlowWorkspaceFixtures } from "../adapters/frontend/core/flow/fileHelpers";
import { BackendPreviewClient } from "../adapters/frontend/backendPreview";
import { getFrontendApiKey } from "./frontendCommon";
import type { WindmillBackendSettings } from "../core/windmillBackendSettings";
import {
  normalizeFlowInitialFixture,
  normalizeFlowStateFixture,
  type FlowInitialFixture,
} from "./flowFixtures";

export function createFlowModeRunner(
  modelConfig: FrontendEvalModelConfig,
  backendValidation: BackendValidationSettings | undefined,
  backendSettings: WindmillBackendSettings,
): ModeRunner<FlowInitialFixture, FlowState, FlowState> {
  return {
    mode: "flow",
    concurrency: 5,
    judgeThreshold: 80,
    async loadInitial(path) {
      if (!path) {
        return undefined;
      }
      return normalizeFlowInitialFixture(await readJsonFile<unknown>(path));
    },
    async loadExpected(path) {
      if (!path) {
        return undefined;
      }
      return normalizeFlowStateFixture(await readJsonFile<unknown>(path));
    },
    async run(prompt, initial, context) {
      const result = await runFlowEval(
        prompt,
        getFrontendApiKey(modelConfig.provider),
        {
          initialFlow: initial?.flowFixture,
          workspaceFixtures: initial?.workspace,
          maxIterations: context.evalCase?.runtime?.maxTurns,
          provider: modelConfig.provider,
          model: modelConfig.model,
          backend: backendSettings,
          runContext: context,
        },
      );

      return {
        success: result.success,
        actual: normalizeFlowStateFixture(result.flow),
        error: result.error,
        assistantMessageCount: result.assistantMessageCount,
        toolCallCount: result.toolCallCount,
        toolsUsed: result.toolsUsed,
        toolCallDetails: result.toolCallDetails,
        skillsInvoked: [],
        tokenUsage: result.tokenUsage,
        finalContextTokens: result.finalContextTokens,
      };
    },
    validate({ evalCase, actual, initial, expected }) {
      return validateFlowState({
        actual,
        initial: initial?.flowState,
        expected,
        validate: evalCase.validate as FlowValidationSpec | undefined,
      });
    },
    async backendValidate({ evalCase, initial, actual, context }) {
      if (
        backendValidation?.mode !== "preview" ||
        !evalCase.runtime?.backendPreview
      ) {
        return null;
      }

      if (!actual.value) {
        return {
          checks: [
            {
              name: "backend flow preview succeeded",
              passed: false,
              details: "Generated flow is missing value.modules",
            },
          ],
        };
      }

      const previewClient = new BackendPreviewClient(backendValidation);
      return await previewClient.withWorkspace(
        evalCase.id,
        context.attempt,
        async (workspaceId) => {
          await seedWorkspaceFixtures(
            previewClient,
            workspaceId,
            initial?.workspace,
          );

          const completedJob = await previewClient.runFlowPreview({
            workspaceId,
            value: actual.value as Record<string, unknown>,
            args: evalCase.runtime?.backendPreview?.args ?? {},
            timeoutSeconds: evalCase.runtime?.backendPreview?.timeoutSeconds,
          });

          return {
            checks: [
              {
                name: "backend flow preview succeeded",
                passed: completedJob.success,
                details: completedJob.success
                  ? `workspace=${workspaceId}`
                  : `workspace=${workspaceId}; job=${completedJob.id}`,
              },
            ],
            artifactFiles: [
              {
                path: "backend-preview.json",
                content:
                  JSON.stringify(
                    {
                      workspaceId,
                      jobId: completedJob.id,
                      success: completedJob.success,
                      result: completedJob.result,
                      logs: completedJob.logs,
                      completedJob: completedJob.raw,
                    },
                    null,
                    2,
                  ) + "\n",
              },
            ],
          };
        },
      );
    },
    buildArtifacts(actual): BenchmarkArtifactFile[] {
      return [
        {
          path: "flow.json",
          content: JSON.stringify(actual, null, 2) + "\n",
        },
      ];
    },
  };
}

async function seedWorkspaceFixtures(
  previewClient: BackendPreviewClient,
  workspaceId: string,
  fixtures?: FlowWorkspaceFixtures,
): Promise<void> {
  for (const script of fixtures?.scripts ?? []) {
    await previewClient.createScript({
      workspaceId,
      path: script.path,
      summary: script.summary,
      description: script.description,
      schema: script.schema,
      content: script.content,
      language: script.language,
    });
  }

  for (const flow of fixtures?.flows ?? []) {
    await previewClient.createFlow({
      workspaceId,
      path: flow.path,
      summary: flow.summary,
      description: flow.description,
      schema: flow.schema,
      value: flow.value as Record<string, unknown>,
    });
  }
}

import { describe, expect, it } from "bun:test";
import { validateFlowState } from "../core/validators";
import { normalizeFlowInitialFixture } from "./flowFixtures";

describe("normalizeFlowInitialFixture", () => {
  it("preserves initial flow metadata for validation", () => {
    const initialFlow = {
      summary: "existing summary",
      value: {
        modules: [
          {
            id: "a",
            value: {
              type: "rawscript",
              language: "bun",
              content: "export async function main() { return 1; }",
              input_transforms: {},
            },
          },
        ],
      },
      schema: {
        $schema: "https://json-schema.org/draft/2020-12/schema",
        properties: {},
        required: [],
        type: "object",
      },
    };

    const initial = normalizeFlowInitialFixture(initialFlow);
    const checks = validateFlowState({
      actual: structuredClone(initialFlow),
      initial: initial.flowState,
    });

    const differsFromInitial = checks.find((check) => check.name === "flow differs from initial");
    expect(initial.flowState?.summary).toBe("existing summary");
    expect(differsFromInitial?.passed).toBe(false);
  });
});

import type { FlowModule } from "../../frontend/src/lib/gen";
import type { FlowFixture } from "../adapters/frontend/core/flow/flowEvalRunner";
import type { FlowWorkspaceFixtures } from "../adapters/frontend/core/flow/fileHelpers";
import type { FlowState } from "../core/validators";

export interface FlowInitialFixture {
  flowFixture?: FlowFixture;
  flowState?: FlowState;
  workspace?: FlowWorkspaceFixtures;
}

export function normalizeFlowInitialFixture(value: unknown): FlowInitialFixture {
  if (isObject(value) && ("flow" in value || "workspace" in value)) {
    const fixture = value as {
      flow?: unknown;
      workspace?: FlowWorkspaceFixtures;
    };
    const flowState = fixture.flow ? normalizeFlowStateFixture(fixture.flow) : undefined;
    return {
      flowState,
      flowFixture: flowState ? normalizeFlowFixture(flowState) : undefined,
      workspace: fixture.workspace,
    };
  }

  const flowState = normalizeFlowStateFixture(value);
  return {
    flowState,
    flowFixture: normalizeFlowFixture(flowState),
  };
}

export function normalizeFlowStateFixture(value: unknown): FlowState {
  if (!isObject(value)) {
    return {};
  }
  if ("flow" in value && isObject((value as { flow?: unknown }).flow)) {
    return (value as { flow: FlowState }).flow;
  }
  return value as FlowState;
}

export function normalizeFlowFixture(value: FlowState): FlowFixture {
  return {
    path: value.path,
    schema: value.schema,
    value: value.value
      ? {
          modules: value.value.modules as FlowModule[] | undefined,
          preprocessor_module: value.value.preprocessor_module as FlowModule | undefined,
          failure_module: value.value.failure_module as FlowModule | undefined,
        }
      : undefined,
  };
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { afterEach, describe, expect, it } from "bun:test";
import { getFrontendApiKey } from "./frontendCommon";

const ORIGINAL_ENV = {
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  OPENAI_API_KEY: process.env.OPENAI_API_KEY,
  GEMINI_API_KEY: process.env.GEMINI_API_KEY,
  DEEPSEEK_API_KEY: process.env.DEEPSEEK_API_KEY,
};

afterEach(() => {
  process.env.ANTHROPIC_API_KEY = ORIGINAL_ENV.ANTHROPIC_API_KEY;
  process.env.OPENAI_API_KEY = ORIGINAL_ENV.OPENAI_API_KEY;
  process.env.GEMINI_API_KEY = ORIGINAL_ENV.GEMINI_API_KEY;
  process.env.DEEPSEEK_API_KEY = ORIGINAL_ENV.DEEPSEEK_API_KEY;
});

describe("getFrontendApiKey", () => {
  it("reads the Gemini API key for googleai models", () => {
    process.env.GEMINI_API_KEY = "gemini-test-key";
    expect(getFrontendApiKey("googleai")).toBe("gemini-test-key");
  });

  it("reads the DeepSeek API key for deepseek models", () => {
    process.env.DEEPSEEK_API_KEY = "deepseek-test-key";
    expect(getFrontendApiKey("deepseek")).toBe("deepseek-test-key");
  });

  it("throws a provider-specific error when the key is missing", () => {
    delete process.env.GEMINI_API_KEY;
    expect(() => getFrontendApiKey("googleai")).toThrow(
      "GEMINI_API_KEY is required for frontend evals",
    );
  });
});

import type { FrontendEvalModelConfig } from "../core/models";

export function getFrontendApiKey(
  provider: FrontendEvalModelConfig["provider"],
): string {
  const envName =
    provider === "anthropic"
      ? "ANTHROPIC_API_KEY"
      : provider === "googleai"
        ? "GEMINI_API_KEY"
        : provider === "deepseek"
          ? "DEEPSEEK_API_KEY"
          : "OPENAI_API_KEY";
  const apiKey = process.env[envName];
  if (!apiKey) {
    throw new Error(`${envName} is required for frontend evals`);
  }
  return apiKey;
}

import { readFile, stat } from "node:fs/promises";
import { basename } from "node:path";
import { loadAppFixtureForEval } from "../adapters/frontend/core/app/appFixtureLoader";
import {
  runGlobalEval,
  type GlobalLiveEditorDraftFixture,
  type GlobalUserFixture,
} from "../adapters/frontend/core/global/globalEvalRunner";
import type { BenchmarkWorkspaceRunnables } from "../adapters/frontend/mockBackend";
import type { FrontendEvalModelConfig } from "../core/models";
import type { BenchmarkArtifactFile, GlobalValidationSpec, ModeRunner } from "../core/types";
import { validateGlobalState, type GlobalDraftState } from "../core/validators";
import type { WindmillBackendSettings } from "../core/windmillBackendSettings";
import { getFrontendApiKey } from "./frontendCommon";

export interface GlobalInitialFixture {
  workspace?: BenchmarkWorkspaceRunnables;
  liveEditorDrafts?: GlobalLiveEditorDraftFixture[];
  user?: GlobalUserFixture;
}

export function createGlobalModeRunner(
  modelConfig: FrontendEvalModelConfig,
  backendSettings: WindmillBackendSettings,
): ModeRunner<GlobalInitialFixture, GlobalDraftState, GlobalDraftState> {
  return {
    mode: "global",
    concurrency: 3,
    judgeThreshold: 80,
    async loadInitial(path) {
      return path ? await loadGlobalInitialFixture(path) : undefined;
    },
    async loadExpected(path) {
      return path ? await loadGlobalExpectedFixture(path) : undefined;
    },
    async run(prompt, initial, context) {
      const result = await runGlobalEval(
        prompt,
        getFrontendApiKey(modelConfig.provider),
        {
          workspaceFixtures: initial?.workspace,
          liveEditorDrafts: initial?.liveEditorDrafts,
          user: initial?.user,
          sessionChat: context.evalCase?.runtime?.sessionChat,
          maxIterations: context.evalCase?.runtime?.maxTurns,
          provider: modelConfig.provider,
          model: modelConfig.model,
          backend: backendSettings,
          runContext: context,
        },
      );

      return {
        success: result.success,
        actual: result.state,
        error: result.error,
        assistantMessageCount: result.assistantMessageCount,
        toolCallCount: result.toolCallCount,
        toolsUsed: result.toolsUsed,
        toolCallDetails: result.toolCallDetails,
        skillsInvoked: [],
        tokenUsage: result.tokenUsage,
        finalContextTokens: result.finalContextTokens,
      };
    },
    validate({ evalCase, actual, expected }) {
      return validateGlobalState({
        actual,
        expected,
        validate: evalCase.validate as GlobalValidationSpec | undefined,
      });
    },
    buildArtifacts(actual): BenchmarkArtifactFile[] {
      return [
        {
          path: "global-drafts.json",
          content: JSON.stringify(actual, null, 2) + "\n",
        },
      ];
    },
  };
}

async function loadGlobalInitialFixture(path: string): Promise<GlobalInitialFixture> {
  if ((await stat(path)).isDirectory()) {
    const { initialFrontend, initialBackend, initialDatatables } =
      await loadAppFixtureForEval(path);
    const name = basename(path);
    return {
      workspace: {
        apps: [
          {
            path: `f/evals/global/${name}`,
            summary: name,
            value: {
              files: initialFrontend,
              runnables: initialBackend,
              data: initialDatatables,
            },
          },
        ],
      },
      liveEditorDrafts: [],
    };
  }

  const parsed = JSON.parse(await readFile(path, "utf8")) as GlobalInitialFixture;
  return {
    workspace: parsed.workspace ?? {},
    liveEditorDrafts: parsed.liveEditorDrafts ?? [],
    user: parsed.user,
  };
}

async function loadGlobalExpectedFixture(path: string): Promise<GlobalDraftState> {
  return JSON.parse(await readFile(path, "utf8")) as GlobalDraftState;
}

import { readJsonFile } from "../core/files";
import type { BackendValidationSettings } from "../core/backendValidation";
import type { FrontendEvalModelConfig } from "../core/models";
import { validateScriptState } from "../core/validators";
import type { BenchmarkArtifactFile, ModeRunner } from "../core/types";
import { BackendPreviewClient } from "../adapters/frontend/backendPreview";
import { runScriptEval } from "../adapters/frontend/core/script/scriptEvalRunner";
import type { ScriptEvalState } from "../adapters/frontend/core/script/fileHelpers";
import { getFrontendApiKey } from "./frontendCommon";
import type { WindmillBackendSettings } from "../core/windmillBackendSettings";

export function createScriptModeRunner(
  modelConfig: FrontendEvalModelConfig,
  backendValidation: BackendValidationSettings | undefined,
  backendSettings: WindmillBackendSettings,
): ModeRunner<ScriptEvalState, ScriptEvalState, ScriptEvalState> {
  return {
    mode: "script",
    concurrency: 5,
    judgeThreshold: 80,
    async loadInitial(path) {
      return path ? await readJsonFile<ScriptEvalState>(path) : undefined;
    },
    async loadExpected(path) {
      return path ? await readJsonFile<ScriptEvalState>(path) : undefined;
    },
    async run(prompt, initial, context) {
      if (!initial) {
        throw new Error("Script evals require an initial script fixture");
      }

      const result = await runScriptEval(
        prompt,
        getFrontendApiKey(modelConfig.provider),
        {
          initialScript: initial,
          maxIterations: context.evalCase?.runtime?.maxTurns,
          provider: modelConfig.provider,
          model: modelConfig.model,
          backend: backendSettings,
          runContext: context,
        },
      );

      return {
        success: result.success,
        actual: result.script,
        error: result.error,
        assistantMessageCount: result.assistantMessageCount,
        toolCallCount: result.toolCallCount,
        toolsUsed: result.toolsUsed,
        toolCallDetails: result.toolCallDetails,
        skillsInvoked: [],
        tokenUsage: result.tokenUsage,
        finalContextTokens: result.finalContextTokens,
      };
    },
    validate({ actual, initial, expected }) {
      return validateScriptState({ actual, initial, expected });
    },
    async backendValidate({ evalCase, initial, actual, context }) {
      if (backendValidation?.mode !== "preview") {
        return null;
      }

      const previewClient = new BackendPreviewClient(backendValidation);
      return await previewClient.withWorkspace(
        evalCase.id,
        context.attempt,
        async (workspaceId) => {
          const completedJob = await previewClient.runScriptPreview({
            workspaceId,
            content: actual.code,
            args:
              (evalCase.runtime?.backendPreview?.args as
                | Record<string, unknown>
                | undefined) ??
              actual.args ??
              initial?.args ??
              {},
            language: normalizePreviewLanguage(actual.lang),
            path: toPreviewScriptPath(actual.path),
            timeoutSeconds: evalCase.runtime?.backendPreview?.timeoutSeconds,
          });

          return {
            checks: [
              {
                name: "backend script preview succeeded",
                passed: completedJob.success,
                details: completedJob.success
                  ? `workspace=${workspaceId}`
                  : `workspace=${workspaceId}; job=${completedJob.id}`,
              },
            ],
            artifactFiles: [
              {
                path: "backend-preview.json",
                content:
                  JSON.stringify(
                    {
                      workspaceId,
                      jobId: completedJob.id,
                      success: completedJob.success,
                      result: completedJob.result,
                      logs: completedJob.logs,
                      completedJob: completedJob.raw,
                    },
                    null,
                    2,
                  ) + "\n",
              },
            ],
          };
        },
      );
    },
    buildArtifacts(actual): BenchmarkArtifactFile[] {
      return [
        {
          path: "script.json",
          content: JSON.stringify(actual, null, 2) + "\n",
        },
        {
          path: actual.path,
          content: actual.code,
        },
      ];
    },
  };
}

function normalizePreviewLanguage(language: ScriptEvalState["lang"]): string {
  return language === "bunnative" ? "bun" : language;
}

function toPreviewScriptPath(filePath: string): string {
  return filePath.replace(/\.[^.\/]+$/, "");
}

